	public function itemwisesearch() {
		$criteria = new CDbCriteria;

		$criteria->with = array(
        'itemDetail' => array(
					'together' => true,
            'select' => 'id, bar_code', // Only select needed columns
            'joinType' => 'INNER JOIN' // Use INNER JOIN if you don't need NULL records
        ),
        'item' => array(
					'together' => true,
            'select' => 'id, title, item_code', // Only select needed columns
            'joinType' => 'INNER JOIN'
        ),
        'order' => array(
					'together' => true,
            'select' => 'id, bill_no, bill_date', // Only select needed columns
            'joinType' => 'INNER JOIN'
        )
    );
		$criteria->group = 'item_detail_id';
		// MySQL 5.7 sorted GROUP BY results implicitly; MySQL 8.0 does not. Order
		// explicitly by the grouped columns to preserve the previous output order.
		$criteria->order = 'item_detail_id';
		
		if ((Yii::app ()->session ['start_date'] != '') && (Yii::app ()->session ['end_date'] != '')) {
			$order_ids = array();
			$criteria1 = new CDbCriteria();
			$criteria1->addBetweenCondition ( 't.bill_date', Yii::app ()->session ['start_date'], Yii::app ()->session ['end_date'] );
			$orders = Order::model()->findAll($criteria1);
			if($orders){
				foreach($orders as $order){
					$order_ids[] = $order->id;
				}
			}
			$criteria->addInCondition('t.order_id',$order_ids);
			
		}
		
		
		
	
		if(!empty(Yii::app()->session['item_id'])){
			$criteria->addInCondition('item.id', Yii::app()->session['item_id']);
		}else{
			$criteria->compare('item.title', $this->item_id ,true);
		}
		$criteria->compare('order.customer_id', $this->customer_id);
		$criteria->compare('itemDetail.bar_code', $this->item_detail_id ,true);

		$criteria->compare('t.tax_amount', $this->tax_amount,true);
		$criteria->compare('t.order_id', $this->order_id);
		$criteria->compare('t.tax_id', $this->tax_id);
	
		$criteria->compare('t.qty', $this->qty);
		$criteria->compare('t.price', $this->price,true);

		$criteria->compare('t.discount_amt', $this->discount_amt,true);

		/* $orderitems = OrderItem::model()->findAll($criteria);
		if($orderitems){
		$total = 0;
			foreach($orderitems as $orderitem){
				
				$total = $total + $orderitem->getItemTotalAmount();
			}
		Yii::app ()->session ['itemwise_total_amt']=number_format($total,2);
		} */
		return new CActiveDataProvider($this, array(
				'criteria' => $criteria,
				'sort'=>array(
						'defaultOrder'=>'t.id DESC',
				),
		));
	}

