		Yii::log ( CVarDumper::dumpAsString ( Yii::app()->session['order_item_end_date']  ), CLogger::LEVEL_WARNING, '$order_item_end_date' );
		if($orders){
			foreach($orders as $order){
				$order_ids[] = $order->id;
			}
		}
