		$criteria->compare('order.bill_no', $this->order_id);
		$criteria->compare('order.customer_id', $this->customer_id);
		$criteria->compare('order.create_user_id', $this->create_user_id);
		$criteria->compare('order.total_amt', $this->total_amt);
		$criteria->compare('item.mrp', $this->mrp);
		$criteria->compare('itemDetail.bar_code', $this->item_detail_id ,true);
		
		$criteria->compare('t.tax_id', $this->tax_id);
		$criteria->compare('t.tax_amount', $this->tax_amount);
		
		$criteria->compare('t.qty', $this->qty);
		$criteria->compare('t.price', $this->price);
		$criteria->compare('t.discount_id', $this->discount_id);
		$criteria->compare('t.discount_amt', $this->discount_amt);
	
		

		return new CActiveDataProvider($this, array(
